-- KAVACH collection: 1 collection + 6 steel-bracelet watches. Safe to re-run.
-- All six watches are live.
-- Price 1,999, MRP 4,999. Case 40 mm, bracelet 20 mm, water resistance 3 ATM are working estimates: confirm with supplier and edit in Admin → Products.
alter table collections add column if not exists tagline_hi text, add column if not exists headline_hi text, add column if not exists description_hi text, add column if not exists story_hi text, add column if not exists meaning_hi text, add column if not exists show_glow boolean default true;
alter table products add column if not exists tags jsonb default '[]'::jsonb, add column if not exists hindi_line text, add column if not exists tagline_hi text, add column if not exists description_hi text, add column if not exists long_description_hi text, add column if not exists stock_mode text default 'in_stock';

insert into collections(slug,name,theme,tagline,headline,description,variants_label,sanskrit,meaning,story,dial_color,sort,image,tagline_hi,headline_hi,description_hi,meaning_hi,story_hi,active,show_glow)
values ('kavach','KAVACH','kavach',$q$Worn like armour. Kept like an heirloom.$q$,$q$Yuga is an age. Astra is the instrument. Kavach is what it wears.$q$,$q$Kavach is armour. This line is steel from end to end: a round case, a three-link bracelet and a sunray dial with nothing on it but twelve faceted batons and the YUGASTRA name.$q$,'6 watches','कवच',$q$Kavach · armour · steel worked until it holds the light$q$,$q$Yuga is an age. Astra is the instrument. Kavach is what it wears: steel, worked until it holds the light.$q$,'Navy',7,$q$https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-KVC-SS-NV.png$q$,$q$कवच की तरह धारण किया, धरोहर की तरह सहेजा।$q$,$q$युग एक काल है। अस्त्र साधन है। कवच वह है जो वह धारण करता है।$q$,$q$कवच रक्षा-आवरण है। यह शृंखला आदि से अंत तक इस्पात की है: गोलाकार आवरण, तीन-कड़ी का ब्रेसलेट, और एक सूर्य-किरण डायल जिस पर बारह पहलदार पट्टिकाओं और YUGASTRA नाम के सिवा कुछ नहीं।$q$,$q$कवच · रक्षा-आवरण · इस्पात, जिसे प्रकाश थामने तक गढ़ा गया$q$,$q$युग एक काल है। अस्त्र साधन है। कवच वह है जो वह धारण करता है: इस्पात, जिसे प्रकाश थामने तक गढ़ा गया।$q$,true,true)
