insert into products(slug,name,sku,tagline,description,long_description,case_color,strap_color,price,compare_price,stock,edition_total,edition_sold,featured,sort,seo_title,seo_description,tagline_hi,description_hi,long_description_hi,collection_id,features,specs,images,stock_mode,active,tags)
select $q$kavach-samudra$q$,$q$KAVACH Samudra$q$,$q$YG-KVC-SS-NV$q$,$q$The deep, kept.$q$,$q$A round watch in stainless steel, on a three-link steel bracelet, with a navy sunray dial and silver hands.$q$,$q$Samudra is the ocean at the last light: a deep navy sunray dial that darkens toward the edge, set in polished steel.

Twelve faceted batons catch the light, with fine minute ticks around the edge and the YUGASTRA name raised above the centre. The crown carries the Λ, the mark of the brand.

The case is brushed on the flanks and polished on the bevels. The bracelet follows it, brushed on the centre links and polished at the edges. The case back is engraved with the YUGASTRA name.$q$,$q$Stainless steel$q$,$q$Stainless steel$q$,1999,4999,50,0,0,false,201,$q$KAVACH Samudra | Navy Dial Steel Bracelet Watch | YUGASTRA$q$,$q$KAVACH Samudra: round steel watch on a steel bracelet. Navy sunray dial, silver hands. 1-year warranty. ₹1,999.$q$,$q$गहरा, सहेजा हुआ।$q$,$q$गोलाकार इस्पात की घड़ी, तीन-कड़ी के इस्पात ब्रेसलेट पर, नील सूर्य-किरण डायल और रजत सुइयाँ।$q$,$q$समुद्र अंतिम प्रकाश में है: गहरा नील सूर्य-किरण डायल, जो किनारे की ओर और गहरा होता जाता है, पॉलिश किए गए इस्पात में जड़ा हुआ।

बारह पहलदार पट्टिकाएँ प्रकाश को थामती हैं, बारीक मिनट-चिह्न किनारे पर हैं और YUGASTRA नाम केंद्र के ऊपर उभरा है। क्राउन पर Λ है, जो ब्रांड का चिह्न है।

आवरण के पार्श्व सतही और धार पॉलिश की हुई है। ब्रेसलेट उसी का अनुसरण करता है: बीच की कड़ियाँ सतही, किनारे पॉलिश किए हुए। केस-बैक पर YUGASTRA अंकित है।$q$,c.id,$q$["Round stainless steel case, brushed and polished", "Three-link stainless steel bracelet", "Navy sunray dial, silver faceted batons and hands", "Raised YUGASTRA wordmark, Λ crown", "Engraved case back", "Japanese quartz movement", "1-year warranty"]$q$::jsonb,$q${"Collection": "KAVACH", "Movement": "Japanese quartz", "Case": "Round, 40 mm, stainless steel", "Strap": "Three-link stainless steel bracelet, 20 mm", "Dial": "Navy sunray, silver hands", "Water resistance": "3 ATM, splash resistant", "Markers": "Twelve faceted batons", "Hands": "Three, silver", "Warranty": "1 year"}$q$::jsonb,$q$["https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-KVC-SS-NV.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-KVC-SIDE.png", "https://5n9sx3cugrn0sd1z.public.blob.vercel-storage.com/yugastra/products/YG-KVC-BACK.png"]$q$::jsonb,'in_stock',true,'[]'::jsonb from collections c where c.slug='kavach'
